# ac6 - CLOSEOUT: DELTA PURITY + GROOM REPRODUCIBILITY, base derived at RUN TIME
# (HEAD^ first, then merge-base(main, HEAD), then merge-base(origin/main, HEAD),
# printing every candidate, its rejection reason and the acceptance - the phase_15
# closeout rule; the WAL is deliberately NOT in ALLOWED because it sits BELOW the
# branch base). The ac_hash is RECOMPUTED from the shipped card, never quoted:
# sha256 over the JSON array of the six fenced bash bodies in ac1..ac6 order,
# COMPACT separators, each body CR-stripped and trimmed (the t58 recipe). The
# five canonical headings are checked HERE, at the fence level, because phase_17's
# groom gate1 gap (WAL 1248 W9d) is exactly a card whose headings were not canonical
# and whose groom still looked complete.
test -f docs/issues/t108.md || { echo "ac6 RED: this card is missing - run from the repository root"; exit 1; }
command -v python3 >/dev/null 2>&1 || { echo "ac6 RED: python3 missing"; exit 1; }
python3 - <<'PYAC6' || exit 1
import hashlib, json, os, re, subprocess, sys
CARD = "docs/issues/t108.md"
GROOM = "docs/state/outputs/t108_definer_groom.json"
BUILDER = "docs/state/outputs/t108_builder_build.json"
DELIVERABLES = ["docs/plan.md"]
KEYS = ("GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_OBJECT_DIRECTORY",
        "GIT_COMMON_DIR", "GIT_PREFIX")
def fail(m):
    sys.stderr.write("ac6 RED: " + m + "\n"); raise SystemExit(1)
def cr(b):
    return b.replace(b"\r\n", b"\n")
def env():
    return {k: v for k, v in os.environ.items() if k not in KEYS}
def git(args):
    p = subprocess.run(["git"] + args, capture_output=True, env=env())
    return cr(p.stdout or b""), (p.stderr or b"").decode("utf-8", "replace"), p.returncode
def rev(spec):
    out, _, rc = git(["rev-parse", "--revs-only", spec])
    r = out.decode("utf-8", "replace").strip()
    return r if rc == 0 and r else ""
def merge_base(ref):
    if not rev(ref):
        return ""
    out, _, rc = git(["merge-base", ref, "HEAD"])
    b = out.decode("utf-8", "replace").strip()
    return b if rc == 0 and b else ""
def blob_at(rev_, path):
    probe, _, rc = git(["rev-parse", "--verify", "-q", "%s:%s" % (rev_, path)])
    if rc != 0 or not probe.strip():
        return None
    out, err, _ = git(["show", "%s:%s" % (rev_, path)])
    if not out:
        fail("blob %s:%s unreadable" % (rev_, path))
    return out
def rejection(cand):
    if not cand:
        return "unresolvable on this checkout"
    if cand == rev("HEAD"):
        return "is HEAD itself, not a base"
    _, _, rc = git(["merge-base", "--is-ancestor", cand, "HEAD"])
    if rc != 0:
        return "is not an ancestor of HEAD"
    w = cr(open("docs/plan.md", "rb").read())
    at = blob_at(cand, "docs/plan.md")
    if at is not None and at == w:
        return "docs/plan.md already equals its blob there - that commit carries the PRODUCT, so diffing against it would make the purity check vacuous"
    return ""
CANDIDATES = [("HEAD^ (the branch parent)", rev("HEAD^")),
              ("merge-base(main, HEAD)", merge_base("main")),
              ("merge-base(origin/main, HEAD)", merge_base("origin/main"))]
BASE = BASE_LABEL = ""
for label, cand in CANDIDATES:
    if BASE:
        print("ac6 evidence: base candidate %s -> %s not tested (the base is already resolved)" % (label, cand[:7] or "(none)"))
        continue
    why = rejection(cand)
    if why:
        print("ac6 evidence: base candidate %s -> %s rejected: %s" % (label, cand[:7] or "(none)", why))
    else:
        BASE, BASE_LABEL = cand, label
        print("ac6 evidence: base candidate %s -> %s ACCEPTED (strict pre-product ancestor of HEAD)" % (label, cand[:7]))
if not BASE:
    fail("no candidate base is a strict pre-product ancestor of HEAD - name the branch shape and re-groom rather than pin a literal")
def names(args):
    out, err, rc = git(args)
    if rc != 0:
        fail("git %s failed: %s" % (" ".join(args), err[:160]))
    return [p for p in out.decode("utf-8", "replace").split("\n") if p.strip()]
tracked_delta = sorted(set(names(["diff", "--name-only", BASE])
                           + names(["diff", "--name-only", "--cached", BASE])))
ALLOWED = set(DELIVERABLES + [CARD, GROOM, BUILDER])
extra = sorted(set(tracked_delta) - ALLOWED)
if extra:
    fail("the delta touches %s beyond plan.md, this card and its two handoffs" % ", ".join(extra))
print("ac6 evidence: delta against %s is exactly: %s" % (BASE[:7], ", ".join(tracked_delta) if tracked_delta else "(nothing)"))
POLLUTION_ROOTS = ("scratch", "build", "node_modules", ".venv", ".pytest_cache",
                   ".pi-agent", "__pycache__")
untracked = names(["ls-files", "--others", "--exclude-standard"])
strays, exc = [], []
for p in untracked:
    if any(root in p.split("/") for root in POLLUTION_ROOTS) or p.endswith(".pyc"):
        exc.append(p)
    elif p.startswith("docs/state/") and not p.endswith(".md"):
        exc.append(p)
    elif p not in ALLOWED:
        strays.append(p)
if strays:
    fail("untracked strays outside the owned surface and the two named exception classes: %s" % ", ".join(sorted(strays)[:12]))
card = cr(open(CARD, "rb").read()).decode("utf-8")
for heading in ("## Context", "## Acceptance criteria", "## Verification commands",
                "## Out of scope", "## Definition of Done"):
    if heading not in card:
        fail("the shipped card lacks the canonical heading '%s' - gate 1 reads these five and phase_17's groom gate1 gap is the precedent this card must not repeat" % heading)
blocks = re.findall(r"(?ms)^### (ac\d+) - .*?^```bash\n(.*?)^```\n", card)
if not blocks:
    fail("no fenced bash blocks found in the shipped card - the ac_hash cannot be recomputed")
ids = [b[0] for b in blocks]
if len(blocks) != 6 or ids != ["ac1", "ac2", "ac3", "ac4", "ac5", "ac6"]:
    fail("the shipped card carries %d fences %s, not the six in ac1..ac6 order" % (len(blocks), ids))
bodies = [b[1].replace("\r", "").strip() for b in blocks]
digest = hashlib.sha256(json.dumps(bodies, separators=(",", ":")).encode("utf-8")).hexdigest()
print("ac6 evidence: recomputed ac_hash from the shipped fences = %s (t58 recipe)" % digest)
if not os.path.isfile(GROOM):
    fail("%s missing - the ac_hash cannot be cross-checked and Gate 1 has nothing to read" % GROOM)
if not os.path.isfile(BUILDER):
    fail("%s is NOT on this branch - the Definition of Done requires the builder handoff alongside the product" % BUILDER)
h = json.loads(cr(open(GROOM, "rb").read()).decode("utf-8"))
hval = str(h.get("evidence", {}).get("ac_hash", "")).split(":")[-1].strip()
if hval != digest:
    fail("the groom handoff carries ac_hash %s but the shipped fences recompute to %s - the card was edited after grooming, or the hash was not authored from these bytes" % (hval[:16] or "(absent)", digest[:16]))
vc = h.get("evidence", {}).get("verification_commands", {})
bad = [i for i, b in zip(ids, bodies) if cr(str(vc.get(i, "")).encode()).decode().strip() != b]
if bad:
    fail("handoff evidence.verification_commands differ from the shipped fences for %s - Builder and Verifier read the handoff" % bad)
print("ac6 GREEN: DELTA PURE AND GROOM REPRODUCIBLE - the delta against %s is exactly %s, the five canonical headings ship, the six fences recompute to the handoff's ac_hash (%s), and the handoff's verification commands are byte-identical to the shipped fences" % (BASE[:7], ", ".join(os.path.basename(p) for p in tracked_delta), digest[:12]))
PYAC6
